import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Analytics = ({ token }) => {
  const [stats, setStats] = useState({
    totalEntries: 0,
    totalAmount: 0,
    anomalies: 0,
    categories: {},
    recentEntries: []
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchAnalytics();
  }, []);

  const fetchAnalytics = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/ledger-entries', {
        headers: { Authorization: `Bearer ${token}` }
      });

      const entries = response.data;
      const totalEntries = entries.length;
      const totalAmount = entries.reduce((sum, entry) => sum + entry.amount, 0);
      const anomalies = entries.filter(entry => entry.is_anomaly).length;

      // Category breakdown
      const categories = {};
      entries.forEach(entry => {
        categories[entry.category] = (categories[entry.category] || 0) + entry.amount;
      });

      setStats({
        totalEntries,
        totalAmount,
        anomalies,
        categories,
        recentEntries: entries.slice(0, 5)
      });
      setLoading(false);
    } catch (error) {
      console.error('Error fetching analytics:', error);
      setLoading(false);
    }
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR'
    }).format(amount);
  };

  if (loading) {
    return <div className="loading">Loading analytics...</div>;
  }

  return (
    <div className="analytics-container">
      <div className="analytics-header">
        <h1>Analytics Dashboard</h1>
      </div>

      <div className="stats-grid">
        <div className="stat-card">
          <h3>Total Entries</h3>
          <div className="stat-number">{stats.totalEntries}</div>
        </div>

        <div className="stat-card">
          <h3>Total Amount</h3>
          <div className="stat-number">{formatCurrency(stats.totalAmount)}</div>
        </div>

        <div className="stat-card anomaly">
          <h3>Anomalies Detected</h3>
          <div className="stat-number">{stats.anomalies}</div>
        </div>

        <div className="stat-card">
          <h3>Anomaly Rate</h3>
          <div className="stat-number">
            {stats.totalEntries > 0 ? ((stats.anomalies / stats.totalEntries) * 100).toFixed(1) : 0}%
          </div>
        </div>
      </div>

      <div className="analytics-grid">
        <div className="card">
          <h2>Category Breakdown</h2>
          <div className="category-list">
            {Object.entries(stats.categories).map(([category, amount]) => (
              <div key={category} className="category-item">
                <span className="category-name">{category}</span>
                <span className="category-amount">{formatCurrency(amount)}</span>
              </div>
            ))}
          </div>
        </div>

        <div className="card">
          <h2>Recent Entries</h2>
          <div className="recent-entries">
            {stats.recentEntries.map(entry => (
              <div key={entry.id} className={`entry-item ${entry.is_anomaly ? 'anomaly' : ''}`}>
                <div className="entry-desc">{entry.description}</div>
                <div className="entry-amount">{formatCurrency(entry.amount)}</div>
                {entry.is_anomaly && <span className="anomaly-badge">⚠️ Anomaly</span>}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Analytics;
